/*
 * RIEDEL glass recommendation for a product, from RIEDEL's online Wine Glass Guide.
 *
 * App only: the backend does not use this file, so changes need no Apps Script deployment.
 * Data: docs/js/glasses-data.js (generated by tools/build_glasses.py from data/riedel_guide.json).
 *
 * recommend(product) returns null for spirits, otherwise:
 *   { entry, shape, also, url, glasses,        // the RIEDEL guide entry, its glass shape, close second shapes
 *     basis: 'grape' | 'style', from,          // why: the grape or style that matched
 *     note,                                    // short explanation for blends, aliases, defaults
 *     alt: { entry, shape, url, when } | null, // e.g. oaked Chardonnay
 *     unmatched: [grape, ...] }                // grapes without a RIEDEL entry
 * shape is null when nothing matched; unmatched then lists the grapes.
 */
var DrinkventoryGlasses = (function () {
  'use strict';

  var GUIDE = (typeof window !== 'undefined' && window.RIEDEL_GUIDE) ||
    (typeof module !== 'undefined' && module.exports && typeof require === 'function' ? require('./glasses-data.js') : null) ||
    { entries: {}, index_url: '' };

  /** Lower case, no accents, single spaces, letters and digits only. */
  function norm(s) {
    return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/ß/g, 'ss')
      .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  }

  // Grape names and synonyms -> RIEDEL guide entry. Keys are normalized with norm().
  // Pinot Noir, Syrah, Chardonnay and Sauvignon Blanc are resolved in code (old/new world, oak).
  // FALLBACK lists entries for the same grape under another name, used when the first has no glasses.
  var ALIASES = {
    // red
    'aglianico': 'Aglianico',
    'barbera': 'Barbera',
    'blauburgunder': 'Blauburgunder', 'blauer burgunder': 'Blauburgunder',
    'blauer portugieser': 'Blauer Portugieser', 'portugieser': 'Blauer Portugieser',
    'blaufrankisch': 'Blaufränkisch', 'blaufraenkisch': 'Blaufränkisch', 'lemberger': 'Blaufränkisch',
    'blauer lemberger': 'Blaufränkisch', 'kekfrankos': 'Blaufränkisch', 'frankovka': 'Blaufränkisch',
    'bobal': 'Bobal',
    'bonarda': 'Bonarda',
    'cabernet franc': 'Cabernet Franc',
    'cabernet sauvignon': 'Cabernet Sauvignon', 'cabernet': 'Cabernet Sauvignon',
    'cannonau': 'Cannonau',
    'carignan': 'Carignan', 'carignano': 'Carignan', 'carinena': 'Carignan', 'mazuelo': 'Carignan', 'samso': 'Carignan',
    'carmenere': 'Carménère',
    'cinsault': 'Cinsault', 'cinsaut': 'Cinsault',
    'corvina': 'Corvina', 'corvina veronese': 'Corvina',
    'dolcetto': 'Dolcetto',
    'dornfelder': 'Dornfelder',
    'gamay': 'Gamay',
    'graciano': 'Graciano',
    'grenache': 'Grenache/Granacha', 'garnacha': 'Grenache/Granacha', 'granacha': 'Grenache/Granacha',
    'garnacha tinta': 'Grenache/Granacha', 'grenache noir': 'Grenache/Granacha',
    'lagrein': 'Lagrein',
    'lambrusco': 'Lambrusco',
    'malbec': 'Malbec', 'cot': 'Malbec',
    'marselan': 'Marselan',
    'mencia': 'Mencia',
    'merlot': 'Merlot',
    'montepulciano': 'Montepulciano',
    'mourvedre': 'Mourvèdre', 'monastrell': 'Mourvèdre', 'mataro': 'Mourvèdre',
    'nebbiolo': 'Nebbiolo', 'spanna': 'Nebbiolo', 'chiavennasca': 'Nebbiolo',
    'nerello mascalese': 'Nerello Mascalese',
    'nero d avola': 'Nero d\'Avola', 'calabrese': 'Nero d\'Avola',
    'petit verdot': 'Petit Verdot',
    'petite sirah': 'Petite Sirah', 'durif': 'Petite Sirah',
    'pinotage': 'Pinotage',
    'primitivo': 'Primitivo',
    'refosco': 'Refosco', 'refosco dal peduncolo rosso': 'Refosco',
    'sangiovese': 'Sangiovese', 'sangioveto': 'Sangiovese', 'prugnolo gentile': 'Sangiovese', 'brunello': 'Sangiovese',
    'saperavi': 'Saperavi',
    'blauer wildbacher': 'Schilcher', 'schilcher': 'Schilcher',
    'st laurent': 'St. Laurent', 'sankt laurent': 'St. Laurent', 'saint laurent': 'St. Laurent',
    'tannat': 'Tannat',
    'tempranillo': 'Tempranillo', 'tinto fino': 'Tempranillo', 'tinta del pais': 'Tempranillo',
    'tinta roriz': 'Tempranillo', 'aragonez': 'Tempranillo', 'cencibel': 'Tempranillo', 'ull de llebre': 'Tempranillo',
    'tinta de toro': 'Tinta de Toro',
    'teroldego': 'Teroldego',
    'touriga nacional': 'Touriga Nacional',
    'xinomavro': 'Xinomavro',
    'zinfandel': 'Zinfandel',
    'zweigelt': 'Zweigelt', 'blauer zweigelt': 'Zweigelt', 'rotburger': 'Zweigelt',
    // white
    'albarino': 'Albariño', 'alvarinho': 'Albariño',
    'aligote': 'Aligoté',
    'arneis': 'Arneis',
    'auxerrois': 'Auxerrois',
    'bacchus': 'Bacchus',
    'chasselas': 'Chasselas', 'gutedel': 'Chasselas', 'fendant': 'Chasselas',
    'chenin blanc': 'Chenin Blanc', 'chenin': 'Chenin Blanc', 'steen': 'Chenin Blanc',
    'cortese': 'Cortese',
    'falanghina': 'Falanghina',
    'fiano': 'Fiano',
    'friulano': 'Friulano', 'tocai friulano': 'Friulano',
    'furmint': 'Furmint',
    'garnatxa blanca': 'Garnatxa Blanca',
    'grenache blanc': 'Grenache Blanc/Granacha Blanca', 'garnacha blanca': 'Grenache Blanc/Granacha Blanca',
    'gelber muskateller': 'Gelber Muskateller', 'muscat blanc a petits grains': 'Gelber Muskateller',
    'gewurztraminer': 'Gewürztraminer', 'gewuerztraminer': 'Gewürztraminer',
    'godello': 'Godello',
    'greco': 'Greco di Tufo', 'greco di tufo': 'Greco di Tufo',
    'gruner veltliner': 'Grüner Veltliner', 'gruener veltliner': 'Grüner Veltliner', 'veltliner': 'Grüner Veltliner',
    'kerner': 'Kerner',
    'macabeo': 'Macabeo', 'viura': 'Macabeo', 'macabeu': 'Macabeo',
    'malvazija istriana': 'Malvazija Istriana', 'malvasia istriana': 'Malvazija Istriana',
    'marsanne': 'Marsanne',
    'melon de bourgogne': 'Melon de Bourgogne (Muscadet)', 'melon': 'Melon de Bourgogne (Muscadet)', 'muscadet': 'Melon de Bourgogne (Muscadet)',
    'muller thurgau': 'Müller-Thurgau', 'mueller thurgau': 'Müller-Thurgau',
    'muskateller': 'Muskateller', 'muscat': 'Muskateller', 'moscato': 'Muskateller', 'moscatel': 'Muskateller',
    'muskat': 'Muskateller', 'goldmuskateller': 'Muskateller', 'moscato giallo': 'Muskateller',
    'muskat ottonel': 'Muskat-Ottonel', 'muscat ottonel': 'Muskat-Ottonel',
    'neuburger': 'Neuburger',
    'pinot blanc': 'Pinot (Blanc, Grigio, Gris)', 'pinot bianco': 'Pinot (Blanc, Grigio, Gris)',
    'weissburgunder': 'Pinot (Blanc, Grigio, Gris)', 'weisser burgunder': 'Pinot (Blanc, Grigio, Gris)',
    'pinot gris': 'Pinot (Blanc, Grigio, Gris)', 'pinot grigio': 'Pinot (Blanc, Grigio, Gris)',
    'grauburgunder': 'Pinot (Blanc, Grigio, Gris)', 'grauer burgunder': 'Pinot (Blanc, Grigio, Gris)',
    'rulander': 'Pinot (Blanc, Grigio, Gris)', 'ruelaender': 'Pinot (Blanc, Grigio, Gris)',
    'ribolla gialla': 'Ribolla Gialla', 'rebula': 'Ribolla Gialla',
    'riesling': 'Riesling', 'rheinriesling': 'Riesling', 'weisser riesling': 'Riesling',
    'rivaner': 'Rivaner',
    'rotgipfler': 'Rotgipfler',
    'roussanne': 'Roussanne',
    'scheurebe': 'Scheurebe', 'samling 88': 'Scheurebe',
    'semillon': 'Sémillon',
    'sylvaner': 'Sylvaner', 'silvaner': 'Sylvaner', 'gruner silvaner': 'Sylvaner', 'gruener silvaner': 'Sylvaner',
    'timorasso': 'Timorasso',
    'traminer': 'Traminer',
    'trebbiano': 'Trebbiano', 'trebbiano toscano': 'Trebbiano', 'ugni blanc': 'Trebbiano',
    'treixadura': 'Treixadura',
    'verdelho': 'Verdelho',
    'verdicchio': 'Verdicchio', 'turbiana': 'Verdicchio', 'trebbiano di lugana': 'Verdicchio',
    'vermentino': 'Vermentino', 'rolle': 'Vermentino', 'pigato': 'Vermentino', 'favorita': 'Vermentino',
    'vernaccia': 'Vernaccia',
    'viognier': 'Viognier',
    'welschriesling': 'Welschriesling', 'grasevina': 'Welschriesling', 'olaszrizling': 'Welschriesling', 'riesling italico': 'Welschriesling',
    'xarel lo': 'Xarel-Lo', 'xarello': 'Xarel-Lo', 'pansa blanca': 'Xarel-Lo',
    'zierfandler': 'Zierfandler'
  };

  var FALLBACK = {
    'Müller-Thurgau': ['Rivaner'],
    'Gewürztraminer': ['Traminer'],
    'Grenache/Granacha': ['Cannonau'],
    'Melon de Bourgogne (Muscadet)': ['Muscadet'],
    'Pinot Noir Old World': ['Blauburgunder'],
    'Pinot Noir New World': ['Pinot Noir Old World'],
    'Shiraz New World': ['Syrah Old World'],
    'Syrah Old World': ['Shiraz New World'],
    'Ice wine': ['Dessertwine'],
    'Blanc de Noirs': ['Sparkling Wine']
  };

  // Aliases that are a different grape name for the same or a related variety: shown as a note.
  var ALIAS_NOTES = {
    'turbiana': 'Turbiana (Trebbiano di Lugana) is the same grape as Verdicchio.',
    'trebbiano di lugana': 'Trebbiano di Lugana (Turbiana) is the same grape as Verdicchio.',
    'goldmuskateller': 'Goldmuskateller is a Muscat; this uses RIEDEL\'s Muskateller page.',
    'moscato giallo': 'Moscato Giallo is a Muscat; this uses RIEDEL\'s Muskateller page.'
  };

  var NEW_WORLD = ['usa', 'united states', 'us', 'america', 'canada', 'chile', 'argentina', 'australia',
    'new zealand', 'south africa', 'uruguay', 'brazil', 'mexico'];

  function isNewWorld(p) { return NEW_WORLD.indexOf(norm(p.country)) >= 0; }

  function entry(name) {
    var e = GUIDE.entries[name];
    return e && e.shape ? e : null;
  }

  /** Grapes of a product, in order of importance: highest percentage first, else as listed. */
  function grapeList(p) {
    // Commas separate grapes; a comma followed by a digit is a decimal comma ("60,5 %").
    var items = String(p.grapes || '').split(/,(?!\d)/).map(function (raw, i) {
      var pct = raw.match(/(\d+(?:[.,]\d+)?)\s*%/);
      var name = raw.replace(/\d+(?:[.,]\d+)?\s*%/g, '').replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
      return { name: name, pct: pct ? Number(pct[1].replace(',', '.')) : null, i: i };
    }).filter(function (g) { return g.name; });
    if (items.some(function (g) { return g.pct !== null; })) {
      items.sort(function (a, b) { return ((b.pct || 0) - (a.pct || 0)) || (a.i - b.i); });
    }
    return items;
  }

  /** True when a and b differ by at most one inserted, deleted or replaced letter. */
  function oneEdit(a, b) {
    if (Math.abs(a.length - b.length) > 1) return false;
    var i = 0, j = 0, diff = 0;
    while (i < a.length && j < b.length) {
      if (a[i] === b[j]) { i++; j++; continue; }
      if (++diff > 1) return false;
      if (a.length > b.length) i++;
      else if (b.length > a.length) j++;
      else { i++; j++; }
    }
    return diff + (a.length - i) + (b.length - j) <= 1;
  }

  var SPECIAL = ['pinot noir', 'pinot nero', 'spatburgunder', 'spaetburgunder', 'syrah', 'shiraz', 'chardonnay',
    'morillon', 'sauvignon blanc', 'sauvignon', 'muskat sylvaner', 'fume blanc'];

  /** Known grape name for a typed name: exact, or one letter off for names of 7 or more letters. */
  function knownName(k) {
    if (ALIASES[k] || SPECIAL.indexOf(k) >= 0) return k;
    if (k.length < 7) return null;
    var keys = SPECIAL.concat(Object.keys(ALIASES));
    var hits = keys.filter(function (x) { return x.length >= 7 && oneEdit(k, x); });
    return hits.length === 1 ? hits[0] : null;
  }

  var DISPLAY = {
    'spatburgunder': 'Spätburgunder', 'spaetburgunder': 'Spätburgunder', 'weissburgunder': 'Weißburgunder',
    'weisser burgunder': 'Weißer Burgunder', 'rulander': 'Ruländer', 'gruner silvaner': 'Grüner Silvaner',
    'samling 88': 'Sämling 88', 'gruner veltliner': 'Grüner Veltliner', 'muller thurgau': 'Müller-Thurgau',
    'blaufrankisch': 'Blaufränkisch', 'gewurztraminer': 'Gewürztraminer', 'nero d avola': 'Nero d\'Avola'
  };

  /** Readable name for a normalized grape key: the RIEDEL entry name if it is the same grape, else title case. */
  function displayName(k) {
    if (DISPLAY[k]) return DISPLAY[k];
    var e = ALIASES[k];
    if (e && norm(e) === k) return e;
    return k.replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  }

  /** RIEDEL entry for one grape, or null. */
  function grapeEntry(grape, p) {
    var typed = norm(grape);
    var k = knownName(typed);
    if (!k) return null;
    var read = k !== typed ? 'Read "' + grape + '" as ' + displayName(k) + '.' : '';
    var m = grapeEntryKnown(k, p);
    if (m && read) {
      m.note = [read, m.note].filter(Boolean).join(' ');
      m.display = displayName(k);
    }
    return m;
  }

  function grapeEntryKnown(k, p) {
    if (k === 'pinot noir' || k === 'pinot nero' || k === 'spatburgunder' || k === 'spaetburgunder') {
      return { name: isNewWorld(p) ? 'Pinot Noir New World' : 'Pinot Noir Old World' };
    }
    if (k === 'syrah' || k === 'shiraz') {
      return { name: isNewWorld(p) ? 'Shiraz New World' : 'Syrah Old World' };
    }
    if (k === 'chardonnay' || k === 'morillon') {
      return { name: 'Chardonnay (unoaked)', alt: 'Chardonnay (oaked)', when: 'if aged in oak' };
    }
    if (k === 'sauvignon blanc' || k === 'sauvignon' || k === 'muskat sylvaner') {
      return { name: 'Sauvignon Blanc (unoaked)', alt: 'Sauvignon Blanc (oaked)', when: 'if aged in oak' };
    }
    if (k === 'fume blanc') return { name: 'Sauvignon Blanc (oaked)' };
    return ALIASES[k] ? { name: ALIASES[k], note: ALIAS_NOTES[k] } : null;
  }

  /** First entry with glasses among the match and its same-grape fallbacks; adds a note when a fallback is used. */
  function resolve(m) {
    if (!m) return null;
    var names = [m.name].concat(FALLBACK[m.name] || []);
    for (var i = 0; i < names.length; i++) {
      if (!entry(names[i])) continue;
      var out = { name: names[i], note: m.note, alt: m.alt, when: m.when, display: m.display };
      if (i > 0) {
        out.note = [m.note, 'RIEDEL lists no glasses on its ' + m.name + ' page; this uses its ' + names[i] + ' page for the same grape.']
          .filter(Boolean).join(' ');
      }
      return out;
    }
    return null;
  }

  function has(text, re) { return re.test(norm(text)); }

  /** Style entries for sparkling, sweet, fortified and rosé wines. */
  function styleEntry(p) {
    var t = p.type;
    var all = [p.name, p.producer, p.region, p.country].join(' ');
    if (t === 'sparkling') {
      if (has(all, /\bchampagne\b/)) return has(all, /\brose\b/) ? 'Rosé Champagne' : 'Champagne';
      if (has(all, /\bcava\b/)) return 'Cava';
      if (has(all, /\bprosecco\b/)) return 'Prosecco';
      if (has(all, /\bfranciacorta\b/)) return 'Franciacorta';
      if (has(all, /\bblanc de blancs\b/)) return 'Blanc de Blancs';
      if (has(all, /\bblanc de noirs\b/)) return 'Blanc de Noirs';
      if (has(all, /\bsekt\b/) || ['germany', 'deutschland', 'austria', 'osterreich'].indexOf(norm(p.country)) >= 0) return 'Sekt';
      return 'Sparkling Wine';
    }
    if (t === 'sweet') {
      if (has(all, /\b(eiswein|ice ?wine|icewine)\b/)) return 'Ice wine';
      if (has(all, /\btrockenbeerenauslese\b/)) return 'Trockenbeerenauslese';
      if (has(all, /\bauslese\b/)) return 'Auslese (sweet)';
      if (has(all, /\b(sauternes|barsac)\b/)) return 'Sauternes';
      return 'Dessertwine';
    }
    if (t === 'fortified') {
      if (has(all, /\btawny\b/)) return 'Tawny Port';
      if (has(all, /\b(port|porto)\b/) || norm(p.country) === 'portugal' && has(all, /\bdouro\b/)) return 'Vintage Port';
      if (has(all, /\b(sherry|jerez|xeres|fino|manzanilla|oloroso|amontillado)\b/)) return 'Sherry';
      if (has(all, /\bmadeira\b/)) return 'Madeira';
      return 'Dessertwine';
    }
    if (t === 'rose') return 'Rosé';
    return null;
  }

  function result(name, basis, from, extra) {
    var e = entry(name);
    if (!e) return null;
    var r = { entry: name, shape: e.shape, also: e.also || [], url: e.url, glasses: e.glasses || [], basis: basis, from: from,
      note: '', alt: null, unmatched: [] };
    if (extra) Object.keys(extra).forEach(function (k) { r[k] = extra[k]; });
    if (e.source === 'glass-name') {
      r.note = [r.note, 'RIEDEL\'s guide page for ' + name + ' shows no glasses; these RIEDEL glasses carry its name.'].filter(Boolean).join(' ');
    }
    return r;
  }

  function recommend(p) {
    if (!p || !p.type) return null;
    var wineTypes = ['red', 'white', 'rose', 'orange', 'sparkling', 'sweet', 'fortified'];
    if (wineTypes.indexOf(p.type) < 0) return null;

    var style = styleEntry(p);
    var ms = style ? resolve({ name: style }) : null;
    if (ms) {
      var rs = result(ms.name, 'style', style, { note: ms.note || '' });
      if (rs) return rs;
    }

    var grapes = grapeList(p);
    var unmatched = [];
    for (var i = 0; i < grapes.length; i++) {
      var g = grapes[i];
      var m = resolve(grapeEntry(g.name, p));
      if (!m) { unmatched.push(g.name); continue; }
      var notes = [];
      var name = m.display || g.name;
      var byShare = grapes.some(function (x) { return x.pct !== null; });
      if (i === 0 && grapes.length > 1) {
        notes.push(name + (byShare ? ' has the largest share of the blend.' : ' is listed first in the blend.'));
      } else if (i > 0) {
        notes.push('RIEDEL lists no glass for ' + unmatched.join(', ') + '; ' + name + ' is the next grape' +
          (byShare ? ' by share.' : ' in the list.'));
      }
      if (m.note) notes.push(m.note);
      var r = result(m.name, 'grape', name, { note: notes.join(' ') });
      if (m.alt && entry(m.alt)) {
        var a = entry(m.alt);
        if (a.shape !== r.shape) r.alt = { entry: m.alt, shape: a.shape, url: a.url, when: m.when };
      }
      r.unmatched = unmatched.concat(grapes.slice(i + 1).filter(function (x) {
        return !resolve(grapeEntry(x.name, p));
      }).map(function (x) { return x.name; }));
      return r;
    }

    if (p.type === 'orange') {
      var ro = result('Qvevri Kakhetian', 'style', 'orange wine', {
        note: 'No grape matched. RIEDEL has no entry for orange wine; Qvevri Kakhetian (Georgian amber wine) is the closest style entry.',
        unmatched: unmatched
      });
      if (ro) return ro;
    }
    return { entry: null, shape: null, also: [], url: GUIDE.index_url || '', glasses: [], basis: null, from: null,
      note: '', alt: null, unmatched: unmatched };
  }

  /** Glass shape of a product for statistics, or '' (spirits, no match). */
  function shapeOf(p) {
    var r = recommend(p);
    return r && r.shape ? r.shape : '';
  }

  return { recommend: recommend, shapeOf: shapeOf, grapeList: grapeList, norm: norm, guide: GUIDE, ALIASES: ALIASES, FALLBACK: FALLBACK };
})();

if (typeof module !== 'undefined' && module.exports) { module.exports = DrinkventoryGlasses; }
